// Shared additive MCP response contract. Existing result fields stay at the top level.
/* eslint-disable no-control-regex -- sanitizing untrusted terminal controls */
import { z } from 'zod';

/** Strip terminal instructions and credential-bearing URL parts before exposing text. */
export function sanitizeMcpText(value) {
  const text = String(value)
    .replace(/(?:\u001b\]|\u009d)[\s\S]*?(?:\u0007|\u001b\\|\u009c|$)/g, '')
    .replace(/(?:\u001b[P^_X]|[\u0090\u0098\u009e\u009f])[\s\S]*?(?:\u001b\\|\u009c|$)/g, '')
    .replace(/(?:\u001b\[|\u009b)[0-?]*[ -/]*(?:[@-~]|$)/g, '')
    .replace(/\u001b[ -/]*[@-~]/g, '')
    // eslint-disable-next-line no-misleading-character-class -- remove each invisible filler independently, including adjacent Hangul fillers
    .replace(/[\p{Cc}\p{Cf}\p{Zl}\p{Zp}\p{Cs}\u061c\u115f\u1160\u17b4\u17b5\u180e\u3164\uffa0\u{e0000}-\u{e007f}]/gu, '');
  // A ')' or apostrophe is legal inside URL credentials. Consume the entire
  // non-whitespace token; treating prose punctuation as a boundary leaks its tail.
  // Normalize JSON slash escapes and recognize whole-URL percent encoding too.
  const normalized = text.replace(/\\+u003a/gi, ':').replace(/\\+u002f/gi, '/').replace(/\\+\//g, '/');
  return normalized.replace(/(?:https?|wss?)(?::\/\/|%(?:25)*3a%(?:25)*2f%(?:25)*2f)[^\s]*/gi, (raw) => {
    try {
      for (let depth = 0; depth < 8 && !/^(?:https?|wss?):\/\//i.test(raw); depth++) raw = decodeURIComponent(raw);
      // Keep the exact public links generated by our chain explorer helpers,
      // including harmless punctuation surrounding those known complete paths.
      const publicLink = raw.match(/^(https:\/\/(?:quaiscan\.io|orchard\.quaiscan\.io)\/(?:tx\/0x[0-9a-f]{64}|address\/0x[0-9a-f]{40})\/?)([)\]}.,;!:'"<>]*)$/i);
      if (publicLink) return publicLink[1] + publicLink[2];
      const url = new URL(raw);
      const publicPath = url.protocol === 'https:' && !url.port && ['quaiscan.io', 'orchard.quaiscan.io'].includes(url.hostname)
        && /^\/(?:tx\/0x[0-9a-f]{64}|address\/0x[0-9a-f]{40})\/?$/i.test(url.pathname);
      // Unknown paths can contain short, dotted, padded, escaped or hex-shaped
      // credentials. Their spelling cannot prove they are public identifiers.
      const path = publicPath || url.pathname === '/' ? url.pathname : '/***';
      // All query/fragment values are removed: credential parameter names vary by provider.
      return `${url.protocol}//${url.host}${path}${url.search || url.hash ? '?***' : ''}`;
    } catch { return '[redacted-url]'; }
  });
}

/** JSON-compatible recursive sanitizer; untrusted object keys may also contain URLs/controls. */
export function sanitizeMcpValue(value) {
  if (typeof value === 'string') return sanitizeMcpText(value);
  if (Array.isArray(value)) return value.map(sanitizeMcpValue);
  if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [sanitizeMcpText(key), sanitizeMcpValue(item)]));
  return value;
}

export const OUTPUT_SCHEMA = z.object({
  _hartii: z.object({
    schemaVersion: z.literal(1),
    capabilityVersion: z.literal(1),
    authority: z.enum(['read-only', 'reviewed-wallet', 'legacy-delegated']),
    mode: z.enum(['read-only', 'dry-run', 'live']),
    chainId: z.number().int().positive(),
    network: z.enum(['mainnet', 'orchard']),
    zone: z.literal('cyprus1'),
    chainVerified: z.boolean(),
  }).strict(),
}).passthrough();

export function toolAnnotations({ write = false, local = false, openWorld = !local }) {
  return { readOnlyHint: !write, destructiveHint: write, idempotentHint: !write, openWorldHint: openWorld };
}

export function resultMetadata({ authority = 'read-only', mode = 'read-only', chainId = 9, network = 'mainnet', chainVerified = false } = {}) {
  return { schemaVersion: 1, capabilityVersion: 1, authority, mode, chainId, network, zone: 'cyprus1', chainVerified };
}

export function toolResult(value, metadata, { isError = false } = {}) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Tool returned an invalid object result.');
  // The local capability identity always wins over untrusted response fields. Canonicalize
  // undefined/BigInt identically for old JSON-text clients and structuredContent clients.
  const jsonValue = JSON.parse(JSON.stringify(value, (_key, item) => typeof item === 'bigint' ? item.toString() : item));
  const structuredContent = { ...sanitizeMcpValue(jsonValue), _hartii: metadata };
  return { content: [{ type: 'text', text: JSON.stringify(structuredContent) }], structuredContent, ...(isError ? { isError: true } : {}) };
}
